package com.nequard.network;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="service_monitors") public class ServiceMonitor{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)UUID deviceId;@Column(nullable=false)String name;@Column(nullable=false)String protocol;Integer port;String endpoint,status="UNKNOWN";Long responseTimeMs;Instant lastCheckedAt;public UUID getId(){return id;}public UUID getDeviceId(){return deviceId;}public void setDeviceId(UUID v){deviceId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getProtocol(){return protocol;}public void setProtocol(String v){protocol=v;}public Integer getPort(){return port;}public void setPort(Integer v){port=v;}public String getEndpoint(){return endpoint;}public void setEndpoint(String v){endpoint=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Long getResponseTimeMs(){return responseTimeMs;}public void setResponseTimeMs(Long v){responseTimeMs=v;}public Instant getLastCheckedAt(){return lastCheckedAt;}public void setLastCheckedAt(Instant v){lastCheckedAt=v;}}